<?php
$base='../'; $tituloPagina='Mis compras'; require_once __DIR__ . '/../php/conexion.php'; require_once __DIR__ . '/../php/auth.php'; require_once __DIR__ . '/../php/util.php'; requerirInicio(); if(!esCliente()){header('Location: ../admin/panel.php');exit;}
$id=(int)$_SESSION['usuario']['id_usuario']; $ventas=$conexion->query("SELECT v.id_venta,v.fecha,v.total,GROUP_CONCAT(CONCAT(d.cantidad,' x ',p.nombre_producto) SEPARATOR ' · ') productos FROM ventas v JOIN detalle_venta d ON d.id_venta=v.id_venta JOIN productos p ON p.id_producto=d.id_producto WHERE v.id_usuario=$id GROUP BY v.id_venta,v.fecha,v.total ORDER BY v.fecha DESC"); require_once __DIR__ . '/../php/encabezado.php';
?><main class="container py-5"><p class="eyebrow">HISTORIAL</p><h1>Mis compras</h1><?php mostrarMensaje(); ?><div class="table-responsive mt-4"><table class="table"><thead><tr><th>Pedido</th><th>Fecha</th><th>Productos</th><th>Total</th></tr></thead><tbody><?php while($v=$ventas->fetch_assoc()): ?><tr><td>#<?php echo $v['id_venta']; ?></td><td><?php echo e($v['fecha']); ?></td><td><?php echo e($v['productos']); ?></td><td>$<?php echo number_format($v['total'],2); ?></td></tr><?php endwhile; ?></tbody></table></div></main><?php require_once __DIR__ . '/../php/pie.php'; ?>
